/*
 * Animated GIF, written here, for the same reason the PNG codec is written here.
 *
 * The point of --record is that the demo in the README can be regenerated by
 * anyone who clones the repository, with one command and no tools they have to
 * install first. That rules out shelling out to anything, so: a global colour
 * table built from the frames themselves, and LZW.
 */

#ifndef GIF_H
#define GIF_H

#include <stddef.h>
#include <stdint.h>

#include "png.h"

typedef enum { GIF_OK = 0, GIF_ERR_ARGUMENT, GIF_ERR_MEMORY, GIF_ERR_IO } gif_status_t;

typedef struct gif_writer gif_writer_t;

/*
 * delay_hundredths is what the viewer waits between frames. The palette is built
 * from the first frame handed over, which for this program is representative:
 * the background and the ramp are the whole image.
 */
gif_status_t gif_open(gif_writer_t **writer, const char *path, int width, int height,
                      int delay_hundredths);

/* Colours that will turn up in later frames and are not in the first, which is the
 * only one the table is chosen from: a flock of letters is at rest in the first,
 * in the colours of the text, and flies in the flock's. Each given gets an entry of
 * its own, up to GIF_SEEDS of them in all, as count triples of red, green and blue.
 * Only before the first frame. */
enum { GIF_SEEDS = 32 };
gif_status_t gif_hint_colours(gif_writer_t *writer, const uint8_t *rgb, int count);

/*
 * Colours the table must have, exactly, whatever the first frame shows: in a space
 * a size of bird nobody has flown into view yet, or a hawk still off the screen,
 * would otherwise be drawn in the nearest colour the table has, a red as a grey. A
 * reserved colour takes an entry before anything is counted, exactly as given, in
 * the order given, and whatever else falls in its bucket is drawn in it, a bucket
 * being too small for anyone to tell. Colours that share a bucket share an entry,
 * which is their mean. Calls add to the list, up to GIF_RESERVED_MAX in all, and
 * only before the first frame; with none reserved the palette is exactly what the
 * first frame makes. A call that cannot be kept whole is refused and changes
 * nothing.
 */
enum { GIF_RESERVED_MAX = 32 };
gif_status_t gif_reserve_colours(gif_writer_t *writer, const uint8_t (*colours)[3], int count);

/* RGBA in, alpha ignored: a GIF frame is opaque. */
gif_status_t gif_add_frame(gif_writer_t *writer, const png_image_t *frame);

/* Writes the trailer and closes. Safe on a writer that failed along the way. */
gif_status_t gif_close(gif_writer_t *writer, size_t *bytes_written, int *frames_written);

const char *gif_status_string(gif_status_t status);

#endif
